import {barBeats,totalBeats,getInstrument,notesFor,scoreProject} from './catalog.js';
import {ART} from './instrument-art.js';
import {practiceSettings} from './practice.js';
import {renderPatternScore,notationEvents} from './notation.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderPracticeBar(el,p,value,cursor,{seek,change,jump}){
 const q=practiceSettings(value,p.bars),open=el.querySelector('details')?.open,focus=el.contains(document.activeElement)?document.activeElement.id:null;
 el.innerHTML=`<div class="rehearsal-position"><label for="practice-seek">Playback position <output id="practice-position"></output></label><input id="practice-seek" type="range" min="0" max="${totalBeats(p)-.25}" step=".25" value="${cursor}"><label class="measure-jump">Measure <input id="practice-measure" type="number" min="1" max="${p.bars}" value="${Math.floor(cursor/barBeats(p))+1}"></label><button id="practice-go">Go</button>${p.sectionMarkers?.length?`<label>Section <select id="practice-section"><option value="">Jump to section…</option>${p.sectionMarkers.map(m=>`<option value="${m.beat}">${esc(m.name)} · m. ${m.bar+1}</option>`).join('')}</select></label>`:''}</div><details ${open?'open':''}><summary>Practice tools <span id="practice-summary">${q.enabled?'Loop on':'Tempo & looping'}</span></summary><div class="practice-options-panel"><div class="practice-settings"><label><input id="practice-enabled" type="checkbox" ${q.enabled?'checked':''}> Loop these measures</label><label>First measure<input id="practice-first" type="number" min="1" max="${p.bars}" value="${q.first}"></label><label>Last measure<input id="practice-last" type="number" min="1" max="${p.bars}" value="${q.last}"></label><label>Playback speed<select id="practice-speed">${[.25,.5,.65,.75,.85,1,1.25,1.5].map(v=>`<option value="${v}" ${v===q.speed?'selected':''}>${Math.round(v*100)}%</option>`).join('')}</select></label><label><input id="practice-countIn" type="checkbox" ${q.countIn?'checked':''}> Count in every loop</label><label><input id="practice-ramp" type="checkbox" ${q.ramp?'checked':''}> Gradually increase tempo</label><label>BPM per repeat<input id="practice-step" type="number" min="1" max="20" value="${q.step}"></label><label>Target BPM<input id="practice-target" type="number" min="30" max="240" value="${q.target}"></label></div><p class="practice-hint">Loop measures are inclusive. Count-ins and gradual tempo apply when practice looping is on. Your written tempo stays unchanged.</p></div></details>`;
 const slider=el.querySelector('#practice-seek');slider.oninput=()=>{el.querySelector('#practice-position').textContent=`Measure ${Math.floor(+slider.value/barBeats(p))+1} of ${p.bars}`};slider.onchange=()=>seek(+slider.value);
 el.querySelector('#practice-go').onclick=()=>{const n=el.querySelector('#practice-measure');if(n.reportValidity())jump((+n.value-1)*barBeats(p))};
 el.querySelector('#practice-measure').onkeydown=e=>{if(e.key==='Enter')el.querySelector('#practice-go').click()};
 const section=el.querySelector('#practice-section');if(section)section.onchange=()=>{if(section.value!=='')jump(+section.value)};
 for(const key of ['enabled','first','last','speed','countIn','ramp','step','target']){const input=el.querySelector('#practice-'+key);input.onchange=()=>{if(!input.reportValidity())return;change({...q,[key]:input.type==='checkbox'?input.checked:+input.value})}}
 updatePracticeBar(el,{beat:cursor,tempo:p.bpm*q.speed,pass:1},p);if(focus)el.querySelector('#'+focus)?.focus({preventScroll:true});
}
export function updatePracticeBar(el,pos,p){if(!el||!p)return;const slider=el.querySelector('#practice-seek');if(!slider)return;const measure=Math.min(p.bars,Math.floor(pos.beat/barBeats(p))+1),text=`Measure ${measure} of ${p.bars}`;
 if(document.activeElement!==slider){slider.value=pos.beat;el.querySelector('#practice-position').textContent=text}slider.setAttribute('aria-valuetext',text);
 el.querySelector('#practice-summary').textContent=pos.counting?`Count in · ${pos.remaining}`:`${Math.round(pos.tempo)} BPM${pos.pass>1?' · repeat '+pos.pass:''}`;
}
export function renderMyPart(el,p,project,id,{artwork,choose,listen,seek}){
 const track=p.tracks.find(t=>t.id===id),inst=getInstrument(track.instrument);el.innerHTML=`<div class="view-header"><div><div class="eyebrow">YOUR PLACE IN THE ENSEMBLE</div><h1>My Part</h1><p>Follow your music. Hear how it belongs.</p></div><label class="my-part-picker">Your part<select id="my-part-select">${p.tracks.map(t=>`<option value="${esc(t.id)}" ${t.id===id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div class="part-listening" role="group" aria-label="Listening mode">${[['part','My part'],['ensemble','Ensemble'],['accompaniment','Without my part']].map(([v,l])=>`<button data-listen="${v}" aria-pressed="${(p.partListen||'ensemble')===v}">${l}</button>`).join('')}</div><div class="my-part-stage"><div class="my-part-art ${inst.shape==='recorder'?'is-recorder':''}">${artwork(inst)}</div><div class="my-part-cue"><span class="eyebrow">${esc(track.name)}</span><strong id="my-part-now">Ready</strong><span id="my-part-next"></span><span id="my-part-measure"></span></div></div><div class="my-part-paper"><div id="my-measure-buttons" class="my-measure-buttons"></div><div id="my-part-score"></div></div><p class="practice-hint">Only this part appears here. “Without my part” lets you play along with the rest of the ensemble.</p>`;
 el.querySelector('#my-part-select').onchange=e=>choose(e.target.value);el.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>{el.querySelectorAll('[data-listen]').forEach(x=>x.setAttribute('aria-pressed',x===b));listen(b.dataset.listen)});el.querySelector('#my-measure-buttons').onclick=e=>{const b=e.target.closest('[data-part-seek]');if(b)seek(+b.dataset.partSeek)};el.dataset.scoreWindow='';
 const art=ART[inst.id],svg=el.querySelector('.my-part-art svg');if(art&&svg)for(const [slot,shape]of(art.hits||[]).entries()){
 const w=art.width||1536,h=art.height||1024;let node;
 if(shape.points){node=document.createElementNS('http://www.w3.org/2000/svg','polygon');node.setAttribute('points',shape.points.map(([x,y])=>x*w+','+y*h).join(' '))}
 else{const ellipse=!!shape.ellipse,values=shape.ellipse||shape.rect;if(!values)continue;node=document.createElementNS('http://www.w3.org/2000/svg',ellipse?'ellipse':'rect');(ellipse?['cx','cy','rx','ry']:['x','y','width','height']).forEach((k,i)=>node.setAttribute(k,values[i]*(i%2?h:w)))}
 node.setAttribute('class','ensemble-hit');node.dataset.partPitch=shape.noteIndex??slot;svg.append(node);
 }
}
export function updateMyPart(el,p,project,id,pos,running){
 const track=project.tracks.find(t=>t.id===id);if(!track)return;const beat=pos.beat,per=barBeats(project),measure=Math.min(project.bars-1,Math.floor(beat/per)),first=Math.floor(measure/2)*2,key=id+':'+first,ns=notesFor(getInstrument(track.instrument),p.key),label=e=>ns.find(n=>n.note===e.note&&(n.shift||0)===(e.shift||0))?.label||'Hit';
 const active=running?track.events.filter(e=>e.beat<=beat&&e.beat+e.duration>beat):[],next=track.events.filter(e=>e.beat>beat).sort((a,b)=>a.beat-b.beat)[0];
 el.querySelector('#my-part-now').textContent=pos.counting?`Count in · ${pos.remaining}`:running?(active.length?[...new Set(active.map(label))].join(' · '):'Rest'):'Ready';
 el.querySelector('#my-part-next').textContent=next?`Next: ${label(next)} · measure ${Math.floor(next.beat/per)+1}`:'No more notes in this passage';el.querySelector('#my-part-measure').textContent=`Measure ${measure+1} · Beat ${Math.floor((beat%per)/(project.meter==='6/8'?.5:1))+1}`;
 el.querySelector('.my-part-stage').classList.toggle('sounding',active.length>0);
 const pitches=new Set(active.map(e=>ns.findIndex(n=>n.note===e.note&&(n.shift||0)===(e.shift||0))));el.querySelectorAll('[data-part-pitch]').forEach(n=>n.classList.toggle('lit',pitches.has(+n.dataset.partPitch)));
 if(el.dataset.scoreWindow!==key){el.dataset.scoreWindow=key;const count=Math.min(2,project.bars-first),start=first*per,end=(first+count)*per,events=notationEvents(scoreProject(project),track,.25).filter(e=>e.beat<end&&e.beat+e.duration>start).map(e=>({...e,beat:Math.max(start,e.beat)-start,duration:Math.min(end,e.beat+e.duration)-Math.max(start,e.beat)})),score=el.querySelector('#my-part-score');score.innerHTML='';score.setAttribute('role','img');score.setAttribute('aria-label',track.name+', notation for measures '+(first+1)+' to '+(first+count));el.querySelector('#my-measure-buttons').innerHTML=Array.from({length:count},(_,i)=>`<button data-part-seek="${(first+i)*per}">Measure ${first+i+1}</button>`).join('');
 try{renderPatternScore(score,scoreProject({...project,bars:count,measureOffset:first,sectionMarkers:[],tracks:[{...track,muted:false,events}]}),[id],.25)}catch{score.textContent='Notation is unavailable. Refresh the studio to load the score.'}}
 const ids=new Set(active.map(e=>String(e.id)));el.querySelectorAll('[data-event-id]').forEach(n=>n.classList.toggle('current-note',(n.dataset.eventIds||n.dataset.eventId).split(' ').some(id=>ids.has(id))));el.querySelectorAll('[data-part-seek]').forEach(b=>{const on=+b.dataset.partSeek===measure*per;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')});
}
